function navMarkup(active){return nav.map(([href,label])=>href==='podcast.html'?`<span class="nav-parent"><a href="podcast.html" ${(active==='podcast.html'||active==='my-podcast.html')?'aria-current="page"':''}>Podcast</a><button type="button" aria-label="Apri sottomenu Podcast" aria-expanded="false">⌄</button><span class="nav-sub"><a href="podcast.html">Podcast</a><a href="my-podcast.html">My Podcast</a></span></span>`:`<a href="${href}" ${href===active?'aria-current="page"':''}>${label}</a>`).join('')}
function brandMarkup(section){
  const area=section==='my-podcast'?'podcast':section.split('-')[0];
  const brands={
    radio:['radio.html','imland-radio.svg','IMLAND Radio'],
    podcast:['podcast.html','imland-podcast.svg','IMLAND Podcast'],
    eventi:['eventi.html','imland-eventi.svg','IMLAND Eventi'],
    member:['member.html','imland-member.svg','IMLAND Member'],
    news:['news.html','imland-news.png','IMLAND News']
  };
  const brand=brands[area];
  return brand?`<a class="brand brand-logo brand-${area}" href="index.html" aria-label="Torna alla Home"><img src="assets/logos/${brand[1]}" alt="${brand[2]}"></a>`:`<a class="brand brand-logo brand-experience" href="index.html" aria-label="Torna alla Home"><img src="assets/logos/imland-experience.png" alt="IMLAND Experience"></a>`;
}
function searchMarkup(){return `<div class="search-panel" role="search"><label for="site-search">Cerca nel sito</label><input id="site-search" type="search" placeholder="Radio, podcast, eventi…" autocomplete="off"><div class="search-results" aria-live="polite"></div></div>`}
function headerActions(){return `<div class="header-actions"><a class="mini-cta" href="download.html">Scarica l’App</a><a class="account-link" href="auth.html" aria-label="Accedi al tuo account"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="8" r="3.5"></circle><path d="M5.5 20c.35-4.05 2.5-6.1 6.5-6.1s6.15 2.05 6.5 6.1"></path></svg></a><button class="search-toggle" type="button" aria-label="Apri ricerca" aria-expanded="false"><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="11" cy="11" r="6.5"></circle><path d="m16 16 4 4"></path></svg></button><button class="menu" type="button" aria-label="Apri menu" aria-expanded="false" aria-controls="site-menu"></button></div>`}
function renderNewsletter(){return `<section class="newsletter-banner" aria-labelledby="newsletter-title"><div class="newsletter-copy"><p>NEWSLETTER IMLAND</p><h2 id="newsletter-title">Le storie del territorio,<br><em>nella tua inbox.</em></h2><span>Un riepilogo di radio, podcast ed eventi una volta al mese. Niente spam.</span></div><form class="newsletter-form" data-newsletter-form><label for="newsletter-email">La tua email</label><div class="newsletter-field"><input id="newsletter-email" name="email" type="email" placeholder="nome@email.it" autocomplete="email" required><button type="submit">Iscriviti →</button></div><label class="newsletter-consent"><input type="checkbox" required><span>Acconsento a ricevere la newsletter e dichiaro di aver letto la <a href="privacy.html">Privacy Policy</a>. Posso revocare il consenso in qualsiasi momento.</span></label><p class="newsletter-status" role="status" aria-live="polite"></p></form></section>`}
function reviewsBentoMarkup(){const reviews=[
  {name:'Malama',image:'https://www.imlandradio.it/logos/malama.png',text:'Ho creduto nel progetto di Imland dai primissimi giorni. Con Davide e tutto il team è nata una collaborazione che mi ha permesso di fare esperienze stimolanti come ad esempio il podcast, che oltre a permettermi di fare conoscere meglio la mia professione, mi ha dato l\'opportunità di mettermi in gioco in prima persona migliorando il mio modo di comunicare. Entrare nella rete Member mi ha permesso di avere connessioni sul territorio e di conoscere altri professionisti della zona, dai quali prendere spunto per possibili migliorie riguardanti la mia attività. In sintesi esperienza consigliata, e tra anche tu nella famiglia Imland'},
  {name:'CSC Infissi',image:'https://www.imlandradio.it/logos/csc-infissi.png',text:'Servizio impeccabile Davide ed il suo team hanno svolto un lavoro eccezionale, dimostrando grande professionalità e puntualità. Hanno saputo ascoltare ogni mia richiesta e trovare la soluzione perfetta con cortesia e competenza. Un\'esperienza assolutamente positiva che merita il massimo dei voti!'},
  {name:'Andrea Todaro',image:'https://www.imlandradio.it/logos/andrea-todaro-consulente.png',text:'Ho creduto nel progetto di Imland dai primissimi giorni. Con Davide e tutto il team è nata una collaborazione che mi ha permesso di fare esperienze stimolanti come ad esempio il podcast, che oltre a permettermi di fare conoscere meglio la mia professione, mi ha dato l\'opportunità di mettermi in gioco in prima persona migliorando il mio modo di comunicare. Entrare nella rete Member mi ha permesso di avere connessioni sul territorio e di conoscere altri professionisti della zona, dai quali prendere spunto per possibili migliorie riguardanti la mia attività. In sintesi esperienza consigliata, e tra anche tu nella famiglia Imland'}
];return `<section class="reviews-bento" aria-labelledby="reviews-title"><header class="reviews-heading"><h2 id="reviews-title">Recensioni.</h2><p>Le esperienze raccontate da chi fa parte della rete IMLAND.</p></header><div class="reviews-fan" aria-label="Tre recensioni della rete IMLAND">${reviews.map((review,index)=>`<article class="review-card review-card-${index===0?'left':index===1?'main':'right'}"><div class="review-author"><span class="review-avatar"><img src="${review.image}" alt="Logo di ${review.name}"></span><div><strong>${review.name}</strong><span>IMLAND Member</span></div></div><div class="review-stars" aria-label="5 stelle su 5"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 2.8 2.76 5.6 6.18.9-4.47 4.36 1.05 6.15L12 16.9l-5.52 2.91 1.05-6.15L3.06 9.3l6.18-.9L12 2.8Z"/></svg><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 2.8 2.76 5.6 6.18.9-4.47 4.36 1.05 6.15L12 16.9l-5.52 2.91 1.05-6.15L3.06 9.3l6.18-.9L12 2.8Z"/></svg><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 2.8 2.76 5.6 6.18.9-4.47 4.36 1.05 6.15L12 16.9l-5.52 2.91 1.05-6.15L3.06 9.3l6.18-.9L12 2.8Z"/></svg><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 2.8 2.76 5.6 6.18.9-4.47 4.36 1.05 6.15L12 16.9l-5.52 2.91 1.05-6.15L3.06 9.3l6.18-.9L12 2.8Z"/></svg><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m12 2.8 2.76 5.6 6.18.9-4.47 4.36 1.05 6.15L12 16.9l-5.52 2.91 1.05-6.15L3.06 9.3l6.18-.9L12 2.8Z"/></svg></div><blockquote id="review-${index}-text">${review.text}</blockquote><button class="review-toggle" type="button" data-review-toggle aria-expanded="false" aria-controls="review-${index}-text"><span>Estendi</span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m7 10 5 5 5-5"/></svg></button></article>`).join('')}</div></section>`}
function authMarkup(){return `<section class="auth-shell" aria-labelledby="auth-title"><div class="auth-story"><div class="auth-story-copy"><p>IMLAND COMMUNITY</p><h1>Il territorio,<br><em>più vicino.</em></h1><span>Accedi allo spazio personale dedicato alla community IMLAND.</span></div><div class="auth-orbit" aria-hidden="true"><i></i><i></i><i></i><b>IM</b></div><small>Radio · Podcast · Eventi · Member</small></div><div class="auth-panel"><div class="auth-card"><a class="auth-back" href="index.html">← Torna alla Home</a><header><p>AREA PERSONALE</p><h2 id="auth-title">Bentornato.</h2><span>L’accesso verrà attivato quando collegheremo il sistema di autenticazione.</span></header><div class="auth-providers" aria-label="Metodi di accesso esterni"><button type="button" data-auth-unavailable><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M21.6 12.23c0-.71-.06-1.23-.2-1.77h-9.2v3.34h5.4a4.62 4.62 0 0 1-2 3.03l-.02.11 2.9 2.25.2.02c1.84-1.7 2.92-4.2 2.92-6.98Z"></path><path d="M12.2 21.8c2.63 0 4.84-.87 6.45-2.36l-3.08-2.38c-.82.55-1.93.94-3.37.94-2.53 0-4.68-1.71-5.45-4.08l-.1.01-3.02 2.34-.03.1a9.74 9.74 0 0 0 8.6 5.43Z"></path><path d="M6.75 13.92A5.86 5.86 0 0 1 6.43 12c0-.67.12-1.31.31-1.92l-.01-.13-3.06-2.37-.1.05A9.8 9.8 0 0 0 2.4 12c0 1.57.38 3.06 1.2 4.37l3.15-2.45Z"></path><path d="M12.2 6c1.83 0 3.06.79 3.76 1.44l2.75-2.69C17.02 3.18 14.83 2.2 12.2 2.2a9.74 9.74 0 0 0-8.63 5.43l3.17 2.45C7.52 7.71 9.67 6 12.2 6Z"></path></svg><span>Continua con Google</span></button><button type="button" data-auth-unavailable><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M16.7 12.8c0-2.6 2.1-3.9 2.2-4-1.2-1.8-3.1-2-3.8-2-1.6-.2-3.1 1-3.9 1s-2-1-3.4-1c-1.7 0-3.4 1-4.3 2.6-1.9 3.2-.5 8 1.3 10.6.9 1.3 1.9 2.7 3.3 2.6 1.3-.1 1.8-.8 3.4-.8 1.6 0 2.1.8 3.5.8 1.5 0 2.4-1.3 3.2-2.6 1-1.5 1.4-3 1.4-3.1-.1 0-2.9-1.1-2.9-4.1ZM14.1 5.1c.7-.9 1.2-2.1 1.1-3.3-1.1.1-2.4.7-3.2 1.6-.7.8-1.3 2-1.2 3.2 1.2.1 2.5-.6 3.3-1.5Z"></path></svg><span>Continua con Apple</span></button></div><div class="auth-divider"><span>oppure</span></div><form class="auth-form" data-auth-form><label for="auth-email">Email</label><input id="auth-email" name="email" type="email" autocomplete="email" placeholder="nome@email.it" required><div class="auth-password-row"><label for="auth-password">Password</label><button type="button" data-auth-unavailable>Password dimenticata?</button></div><input id="auth-password" name="password" type="password" autocomplete="current-password" placeholder="La tua password" required><label class="auth-remember"><input type="checkbox" name="remember"><span>Ricordami su questo dispositivo</span></label><button class="auth-submit" type="submit">Accedi</button><p class="auth-status" role="status" aria-live="polite"></p></form><p class="auth-register">Non hai ancora un account? <button type="button" data-auth-unavailable>Registrati</button></p></div></div></section>`}
function feedCatalog(feeds){return `<div class="feed-grid">${feeds.map(([title,description,count,image])=>`<article class="feed-card"><img src="${image}" alt="Copertina ${title}" loading="lazy"><div><small>${count} ${count===1?'EPISODIO':'EPISODI'}</small><h2>${title}</h2><p>${description}</p><button class="feed-open" type="button" data-podcast-open data-show="${title}" aria-label="Apri gli episodi di ${title}">Ascolta <svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 7 8 5-8 5V7Z"/></svg></button></div></article>`).join('')}</div><section class="podcast-channel" data-podcast-channel hidden aria-labelledby="podcast-channel-title"><header><img data-channel-image src="assets/logos/imland-podcast.svg" alt="IMLAND Podcast"><div><button type="button" data-channel-close>← Tutti i canali</button><h2 id="podcast-channel-title" data-channel-title></h2><p data-channel-description></p></div></header><div class="episode-list" data-channel-episodes></div></section>`}
function radioCatalog(programs){return `<section class="radio-programs" aria-labelledby="radio-programs-title"><div class="radio-programs-head"><p class="eyebrow">PALINSESTO LIVE</p><h2 id="radio-programs-title">Cinque programmi.<br><em>Una settimana in onda.</em></h2><p>Dal lunedì al venerdì, ogni sera dalle 18:00 alle 19:00.</p></div><div class="radio-program-grid">${programs.map(([title,day,time,speakers,type,image])=>`<article class="radio-program-card"><img src="${image}" alt="Copertina ufficiale di ${title}" loading="lazy"><div class="radio-program-info"><div class="radio-program-slot"><span>${day}</span><strong>${time}</strong></div><h3>${title}</h3><p class="radio-program-type">${type}</p><p class="radio-program-speakers"><span>Speaker</span><strong>${speakers}</strong></p></div></article>`).join('')}</div></section>`}
function territoryNewsMarkup(){return `<section class="territory-news" aria-labelledby="territory-news-title"><header class="news-section-head"><div><h2 id="territory-news-title">Le ultime dal Piemonte.</h2><p>Una rassegna aggiornata dalle principali testate regionali. Ogni articolo si legge sempre sulla fonte originale.</p></div></header><div class="territory-news-grid">${territoryNews.map(([source,place,date,title,summary,image,url])=>`<article class="territory-story"><a class="territory-story-image" href="${url}" target="_blank" rel="noreferrer" aria-label="Leggi su ${source}: ${title}"><img src="${image}" alt="" loading="lazy"></a><div class="territory-story-copy"><p>${source}<span>${place} · ${date}</span></p><h3>${title}</h3><span>${summary}</span><a href="${url}" target="_blank" rel="noreferrer">Leggi su ${source} <b>↗</b></a></div></article>`).join('')}</div></section>`}
function memberNewsMarkup(){const content=syncedMemberNews.length?`<div class="member-news-grid">${syncedMemberNews.map(item=>`<article class="member-news-card"><a href="${escapeSyncText(item.url)}"><img src="${escapeSyncText(item.image)}" alt="" loading="lazy"><span>${escapeSyncText(item.category||'News Member')}</span><h3>${escapeSyncText(item.title)}</h3><p>${escapeSyncText(item.description||'')}</p><b>Leggi →</b></a></article>`).join('')}</div>`:`<div class="member-news-empty" role="status"><span>NEWS MEMBER</span><h3>Le prossime novità della rete<br>appariranno qui.</h3><p>Pubblicheremo solo contenuti inviati e verificati dalla redazione IMLAND.</p><a href="contatti.html">Proponi una News Member <b>→</b></a></div>`;return `<section class="member-news" aria-labelledby="member-news-title"><header class="member-news-head"><div><h2 id="member-news-title">Le News dei Member.</h2><p>Uno spazio dedicato alle novità validate della rete IMLAND.</p></div>${syncedMemberNews.length?'<div class="member-news-filters" role="tablist" aria-label="Filtra le News dei Member"><button type="button" role="tab" aria-selected="true" data-member-filter="all">Tutte</button></div>':''}</header>${content}</section>`}
function syncedEventsMarkup(){if(!syncedEvents.length)return `<div class="empty-editorial"><span>AGENDA IMLAND</span><h2>Appuntamenti presto in arrivo.</h2><p>Stiamo chiudendo le prossime date con i territori. Qui compariranno esclusivamente eventi confermati.</p><a class="button primary" href="contatti.html">Proponi il tuo evento →</a></div>`;return `<section class="events-live-grid" aria-label="Prossimi eventi IMLAND">${syncedEvents.map(item=>`<article><time datetime="${escapeSyncText(item.dateTime||'')}">${escapeSyncText(item.date||'')}</time><h2>${escapeSyncText(item.title)}</h2><p>${escapeSyncText(item.description||'')}</p><a class="button primary" href="${escapeSyncText(item.url||'eventi.html')}">Scopri l’evento →</a></article>`).join('')}</section>`}
function memberArticleMarkup(){return `<article class="member-article" aria-labelledby="member-article-title"><header class="member-article-hero"><a class="member-article-back" href="news.html">← Tutte le News</a><div class="member-article-kicker"><span>NEWS MEMBER</span><i>In attesa di pubblicazione</i></div><h1 id="member-article-title">La tua News Member,<br><em>qui.</em></h1><p>Questo è il layout che ospiterà il titolo, la copertina e il racconto di una realtà Member dopo la verifica redazionale.</p></header><div class="member-article-layout"><aside class="member-article-facts" aria-label="Dettagli dell'articolo"><p>DETTAGLI</p><dl><div><dt>Categoria</dt><dd>Da assegnare</dd></div><div><dt>Pubblicazione</dt><dd>Dopo verifica</dd></div><div><dt>Autore</dt><dd>Da confermare</dd></div><div><dt>Letture</dt><dd>Disponibili alla pubblicazione</dd></div></dl></aside><div class="member-article-story"><div class="member-article-cover"><span>IMLAND MEMBER</span><img src="assets/logos/imland-member.svg" alt="IMLAND Member"><small>SPAZIO PER COPERTINA UFFICIALE</small></div><div class="member-article-copy"><p class="member-article-lead">Ogni notizia Member avrà qui il proprio spazio editoriale: una lettura chiara, firmata e collegata alla realtà che la rende possibile.</p><p>Quando riceveremo i dati validati, sostituiremo questo testo con la notizia completa, le immagini approvate e gli eventuali riferimenti utili. Nessun dettaglio viene pubblicato senza una fonte confermata.</p><div class="member-article-author"><span class="member-article-avatar" aria-hidden="true"><svg viewBox="0 0 24 24"><circle cx="12" cy="8" r="3.5"></circle><path d="M5.5 20c.35-4.05 2.5-6.1 6.5-6.1s6.15 2.05 6.5 6.1"></path></svg></span><div><small>FIRMA DELL'ARTICOLO</small><strong>Profilo autore in attesa di conferma</strong></div></div></div></div></div><footer class="member-article-footer"><span>Una rete di storie locali, da raccontare bene.</span><a href="news.html">Torna alle News <b>→</b></a></footer></article>`}
function memberNetworkMarkup(){const coords=memberNetwork.slice(0,30).map((member,index)=>{const column=index%10;const row=Math.floor(index/10);const x=(column-4.5)*10;const y=(row-1)*10+(column%2?5:0);return `<div class="dome-item" style="--dome-x:${x};--dome-y:${y}"><button type="button" data-member-logo data-name="${member[0]}" data-image="${member[1]}" aria-label="Apri il logo di ${member[0]}"><img src="${member[1]}" alt="${member[0]}"></button></div>`}).join('');return `<section class="member-network" aria-labelledby="member-network-title"><header><h2 id="member-network-title">La rete <em>IMLAND.</em></h2><p>Trascina la cupola e seleziona un logo per esplorare le realtà che compongono la rete Member.</p></header><div class="dome-gallery" data-member-dome><div class="dome-stage"><div class="dome-sphere" data-dome-sphere>${coords}</div></div><div class="dome-shade" aria-hidden="true"></div><div class="dome-hint" aria-hidden="true"><svg viewBox="0 0 24 24"><path d="M7 11V7a2 2 0 0 1 4 0v3-5a2 2 0 0 1 4 0v5-2a2 2 0 0 1 4 0v6c0 4.4-2.6 7-7 7-3 0-4.8-1.3-6.5-3.5L3 14.5a2 2 0 0 1 3-2.6L8 14"/></svg><span>Trascina</span></div><div class="dome-viewer" data-dome-viewer hidden><button type="button" data-dome-close aria-label="Chiudi il logo">×</button><img src="assets/logos/imland-member.svg" alt=""><strong data-dome-name></strong></div></div></section>`}
function memberMapMarkup(){const details=window.IMLAND_MEMBER_DETAILS||{};const logoByName=new Map(memberNetwork);const locations=Object.entries(details).flatMap(([name,item])=>(item.addresses||[]).filter(location=>location.coordinates&&logoByName.has(name)).map(location=>({name,image:logoByName.get(name),...location})));if(!locations.length)return'';const longitudes=locations.map(item=>item.coordinates[0]),latitudes=locations.map(item=>item.coordinates[1]);const minLng=Math.min(...longitudes)-.035,maxLng=Math.max(...longitudes)+.035,minLat=Math.min(...latitudes)-.025,maxLat=Math.max(...latitudes)+.025;const markers=locations.map((location,index)=>{const x=6+((location.coordinates[0]-minLng)/(maxLng-minLng))*88;const y=8+(1-(location.coordinates[1]-minLat)/(maxLat-minLat))*84;const samePlace=locations.slice(0,index).filter(item=>item.coordinates[0]===location.coordinates[0]&&item.coordinates[1]===location.coordinates[1]).length;const angle=samePlace*2.4;const nudge=samePlace?`--nudge-x:${Math.cos(angle)*13}px;--nudge-y:${Math.sin(angle)*13}px;`:'';return `<button class="imland-map-marker" type="button" style="--map-x:${x.toFixed(3)}%;--map-y:${y.toFixed(3)}%;${nudge}" data-map-member="${index}" aria-label="${location.name}, ${location.label}: ${location.address}"><img src="${location.image}" alt=""></button>`}).join('');const first=locations[0];window.IMLAND_MAP_LOCATIONS=locations;return `<section class="imland-map" aria-labelledby="imland-map-title"><header class="imland-map-head"><div><p>LA RETE SUL TERRITORIO</p><h2 id="imland-map-title">IMLAND <em>MAP.</em></h2></div><p>Le sedi Member verificate, posizionate sul territorio. Seleziona un logo per vedere i dettagli.</p></header><div class="imland-map-layout"><div class="imland-map-canvas" role="region" aria-label="Mappa delle sedi IMLAND Member"><svg class="imland-map-drawing" viewBox="0 0 1000 620" aria-hidden="true"><path class="map-boundary" d="M71 112 193 57 322 78 422 43 559 89 687 61 834 111 929 225 891 343 947 465 829 563 673 536 546 592 396 548 268 582 145 512 88 397 113 276Z"/><path class="map-border" d="M240 68c50 85 34 152 105 210s57 171 36 280M534 82c-20 98 58 144 36 236s45 153 78 225M112 281c168 10 274-59 414-25s221 18 390-2M92 410c158-37 257 40 395 3s252-4 402 40"/><path class="map-road map-road-main" d="M72 494C198 434 280 397 379 344S548 268 664 246 817 208 930 135"/><path class="map-road map-road-main" d="M115 132c114 54 211 103 325 142s232 72 447 146"/><path class="map-road" d="M173 562c46-88 121-152 210-201s132-137 155-278M303 77c32 83 85 130 156 181s98 153 105 292M698 67c-56 70-99 145-113 226s52 159 190 248M101 339c134-20 220 21 335 64s251 57 455 4"/><circle class="map-city" cx="282" cy="233" r="5"/><circle class="map-city" cx="480" cy="410" r="5"/><circle class="map-city" cx="690" cy="350" r="5"/><text x="244" y="218">BIELLA</text><text x="431" y="443">VERCELLI</text><text x="706" y="380">NOVARA</text><text x="622" y="123">VERBANO · CUSIO · OSSOLA</text></svg><div class="imland-map-markers">${markers}</div><div class="imland-map-legend"><span><i></i>${locations.length} sedi verificate</span><small>Coordinate cartografiche verificate · OpenStreetMap</small></div></div><aside class="imland-map-card" aria-live="polite"><span class="imland-map-card-logo"><img src="${first.image}" alt="Logo di ${first.name}" data-map-card-image></span><p data-map-card-label>${first.label}</p><h3 data-map-card-name>${first.name}</h3><address data-map-card-address>${first.address}</address><div><b>POSIZIONE VERIFICATA</b><span>Coordinate disponibili per questa sede.</span></div></aside></div><p class="imland-map-note">La mappa mostra esclusivamente sedi con coordinate già verificate. I Member senza coordinate non vengono posizionati con dati presunti.</p></section>`}
function memberDirectoryMarkup(){
  const details=window.IMLAND_MEMBER_DETAILS||{};
  const logoByName=new Map(memberNetwork);
  const cards=Object.entries(details).map(([name,item])=>{
    const logo=logoByName.get(name);
    if(!logo)return '';
    const addresses=(item.addresses||[]).map(location=>`<li><span>${escapeSyncText(location.label||'Sede')}</span><address>${escapeSyncText(location.address||'Indirizzo in aggiornamento')}</address></li>`).join('');
    return `<article class="member-directory-card"><div class="member-directory-logo"><img src="${escapeSyncText(logo)}" alt="Logo di ${escapeSyncText(name)}" loading="lazy"></div><div class="member-directory-copy"><h3>${escapeSyncText(name)}</h3><p>${escapeSyncText(item.description||'')}</p><ul>${addresses}</ul></div></article>`;
  }).join('');
  return `<section class="member-directory" id="rete-member" aria-labelledby="member-directory-title"><header><div><p>MEMBER UFFICIALI</p><h2 id="member-directory-title">Le realtà della <em>rete.</em></h2></div><p>Imprese, professionisti e associazioni che fanno parte di IMLAND Experience. Dati e sedi sono riportati senza informazioni presunte.</p></header><div class="member-directory-grid">${cards}</div></section>`;
}
function initMemberMap(){const root=document.querySelector('.imland-map');const locations=window.IMLAND_MAP_LOCATIONS||[];if(!root||!locations.length)return;const image=root.querySelector('[data-map-card-image]'),name=root.querySelector('[data-map-card-name]'),label=root.querySelector('[data-map-card-label]'),address=root.querySelector('[data-map-card-address]');root.querySelectorAll('[data-map-member]').forEach(button=>button.addEventListener('click',()=>{const location=locations[Number(button.dataset.mapMember)];root.querySelectorAll('[data-map-member]').forEach(marker=>{marker.classList.toggle('is-active',marker===button);marker.removeAttribute('aria-pressed')});image.src=location.image;image.alt=`Logo di ${location.name}`;name.textContent=location.name;label.textContent=location.label;address.textContent=location.address;button.setAttribute('aria-pressed','true')}));root.querySelector('[data-map-member]')?.classList.add('is-active')}
function mapCategory(name,description=''){const value=`${name} ${description}`.toLowerCase();if(/ristor|calici|malama/.test(value))return'Ristorazione e benessere';if(/immobil|tetti|infissi|studio tecnico|modularee/.test(value))return'Casa e immobiliare';if(/industr|carpenter|maglificio|compensati|ricambi|barberi|autotrasport/.test(value))return'Industria e servizi';if(/arte|grafich|design|eventi|musica/.test(value))return'Arte e comunicazione';if(/software|telecom/.test(value))return'Tecnologia';return'Professionisti e territorio'}
function officialMemberMapMarkup(){const details=window.IMLAND_MEMBER_DETAILS||{};const logoByName=new Map(memberNetwork);const locations=Object.entries(details).flatMap(([name,item])=>(item.addresses||[]).filter(location=>location.coordinates&&logoByName.has(name)).map(location=>({name,image:logoByName.get(name),description:item.description||'',category:mapCategory(name,item.description),...location})));if(!locations.length)return'';window.IMLAND_MAP_LOCATIONS=locations;const categories=['Tutte',...new Set(locations.map(item=>item.category))];return `<section class="official-map" aria-labelledby="official-map-title"><header class="official-map-head"><div><p>IMLAND MAP</p><h2 id="official-map-title">Il territorio,<br><em>tutto in un punto.</em></h2></div><div><p>Esplora le aziende, i professionisti e le associazioni della rete IMLAND Member. Filtra per categoria e seleziona un logo sulla mappa.</p><a href="#rete-member">Tutti i Member →</a></div></header><div class="official-map-filters" aria-label="Filtra i Member per categoria">${categories.map((category,index)=>`<button type="button" data-map-category="${category}" aria-pressed="${index===0}">${category}</button>`).join('')}</div><div class="official-map-bento"><div id="imland-live-map" class="official-map-canvas" role="region" aria-label="Mappa interattiva delle sedi IMLAND Member"><div class="official-map-loading">Caricamento della mappa…</div></div><aside class="official-map-detail" aria-live="polite"><span class="official-map-logo"><img data-official-map-image src="${locations[0].image}" alt="Logo di ${locations[0].name}"></span><p data-official-map-category>${locations[0].category}</p><h3 data-official-map-name>${locations[0].name}</h3><address data-official-map-address>${locations[0].address}</address><span data-official-map-description>${locations[0].description}</span></aside></div><p class="official-map-note">La mappa mostra esclusivamente sedi con coordinate cartografiche verificate. Tutti gli indirizzi disponibili, comprese le sedi multiple, restano riportati nelle schede Member.</p></section>`}
function initOfficialMemberMap(){const root=document.querySelector('.official-map');const mapNode=document.querySelector('#imland-live-map');const locations=window.IMLAND_MAP_LOCATIONS||[];if(!root||!mapNode||!locations.length)return;const render=()=>{if(!window.L)return;mapNode.innerHTML='';const map=L.map(mapNode,{scrollWheelZoom:false,zoomControl:true}).setView([45.65,8.38],10);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:18,attribution:'© OpenStreetMap'}).addTo(map);let activeCategory='Tutte';let markers=[];const detail={image:root.querySelector('[data-official-map-image]'),category:root.querySelector('[data-official-map-category]'),name:root.querySelector('[data-official-map-name]'),address:root.querySelector('[data-official-map-address]'),description:root.querySelector('[data-official-map-description]')};const select=location=>{detail.image.src=location.image;detail.image.alt=`Logo di ${location.name}`;detail.category.textContent=location.category;detail.name.textContent=location.name;detail.address.textContent=location.address;detail.description.textContent=location.description};const draw=()=>{markers.forEach(marker=>map.removeLayer(marker));markers=[];const visible=locations.filter(item=>activeCategory==='Tutte'||item.category===activeCategory);visible.forEach(location=>{const logoUrl=encodeURI(location.image).replace(/'/g,'%27');const icon=L.divIcon({className:'official-logo-marker',html:`<span style="background-image:url('${logoUrl}')" aria-hidden="true"></span>`,iconSize:[46,46],iconAnchor:[23,23]});const marker=L.marker([location.coordinates[1],location.coordinates[0]],{icon,title:location.name}).addTo(map).on('click',()=>select(location));markers.push(marker)});if(markers.length){const group=L.featureGroup(markers);map.fitBounds(group.getBounds().pad(.16),{maxZoom:12});select(visible[0])}};root.querySelectorAll('[data-map-category]').forEach(button=>button.addEventListener('click',()=>{activeCategory=button.dataset.mapCategory;root.querySelectorAll('[data-map-category]').forEach(item=>item.setAttribute('aria-pressed',String(item===button)));draw()}));draw();setTimeout(()=>map.invalidateSize(),100)};if(window.L){render();return}const css=document.createElement('link');css.rel='stylesheet';css.href='https://unpkg.com/leaflet@1.9.4/dist/leaflet.css';document.head.append(css);const script=document.createElement('script');script.src='https://unpkg.com/leaflet@1.9.4/dist/leaflet.js';script.onload=render;script.onerror=()=>{mapNode.innerHTML='<p class="official-map-loading">La cartografia non è disponibile. Le sedi verificate restano consultabili nelle schede Member.</p>'};document.head.append(script)}
function downloadMarkup(){return `<section class="download-page" aria-labelledby="download-title"><div class="download-copy"><img src="assets/logos/imland-experience.png" alt="IMLAND Experience"><h1 id="download-title">Tutto IMLAND.<br><em>In tasca.</em></h1><p>Radio, podcast, eventi e storie dal territorio: l'app IMLAND sta arrivando sul tuo telefono.</p><div class="download-choices" aria-label="Canali di download"><button class="store-badge" type="button" data-download-unavailable><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M16.7 12.8c0-2.6 2.1-3.9 2.2-4-1.2-1.8-3.1-2-3.8-2-1.6-.2-3.1 1-3.9 1s-2-1-3.4-1c-1.7 0-3.4 1-4.3 2.6-1.9 3.2-.5 8 1.3 10.6.9 1.3 1.9 2.7 3.3 2.6 1.3-.1 1.8-.8 3.4-.8 1.6 0 2.1.8 3.5.8 1.5 0 2.4-1.3 3.2-2.6 1-1.5 1.4-3 1.4-3.1-.1 0-2.9-1.1-2.9-4.1ZM14.1 5.1c.7-.9 1.2-2.1 1.1-3.3-1.1.1-2.4.7-3.2 1.6-.7.8-1.3 2-1.2 3.2 1.2.1 2.5-.6 3.3-1.5Z"/></svg><span><small>Disponibile su</small>App Store</span></button><button class="store-badge" type="button" data-download-unavailable><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4.2 3.2c-.4.42-.7 1.08-.7 1.92v13.76c0 .84.3 1.5.7 1.92l.1.08 7.7-8.84v-.2L4.3 3.12l-.1.08Zm10.34 5.66-2.3 2.64v.2l2.3 2.64.05-.03 2.72-1.54c.78-.44.78-1.15 0-1.59l-2.72-1.54-.05-.02ZM5.15 21l9.12-5.15-2.3-2.64L4.2 22.05c.3.24.65.34.95.2Zm0-18c-.3-.14-.65-.04-.95.2l7.77 8.84 2.3-2.64L5.15 3Z"/></svg><span><small>Disponibile su</small>Google Play</span></button><button class="scan-chip" type="button" data-download-unavailable><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4 9V5a1 1 0 0 1 1-1h4m6 0h4a1 1 0 0 1 1 1v4M4 15v4a1 1 0 0 0 1 1h4m6 0h4a1 1 0 0 0 1-1v-4"/><path d="M8 8h3v3H8zm5 0h3v3h-3zm-5 5h3v3H8zm5 1h3v2h-3z"/></svg><span>QR per installare</span></button></div><p class="download-status" role="status" aria-live="polite">Link agli store e QR verranno collegati al lancio dell'app.</p></div><div class="phone-stage" aria-label="Anteprima dell'app IMLAND"><div class="app-phone phone-back"><span></span><small>MOCKUP 01</small></div><div class="app-phone phone-middle"><span></span><small>MOCKUP 02</small></div><div class="app-phone phone-front"><div class="phone-notch"></div><img src="assets/logos/imland-experience.png" alt=""><strong>Mockup dell'app<br>in arrivo.</strong><small>MOCKUP 03</small></div></div></section>`}

if(page!=='home'){
  const active=`${page}.html`;
  document.body.innerHTML=`
    <a class="skip" href="#main">Vai al contenuto</a>
    <header class="topbar">
      ${brandMarkup(page)}
      <nav id="site-menu" aria-label="Navigazione principale">${navMarkup(active)}</nav>
      ${headerActions()}
      ${searchMarkup()}
    </header>
    <main id="main">${page==='auth'?authMarkup():page==='news-member'?memberArticleMarkup():page==='download'?downloadMarkup():renderPage(page)}</main>
    ${page==='auth'?'':renderNewsletter()}
    ${renderFooter()}
    ${page==='auth'?'':renderPlayer()}`;
}
if(page==='home')document.querySelector('.cta')?.insertAdjacentHTML('beforebegin',reviewsBentoMarkup());
if(page==='member')document.querySelector('.page-content')?.insertAdjacentHTML('beforeend',officialMemberMapMarkup()+reviewsBentoMarkup());
if(page!=='auth')document.body.insertAdjacentHTML('beforeend',renderFloatingActions());
if(page==='contatti')enhanceContactIcons();
if(page==='member')initMemberDome();
if(page==='member')initOfficialMemberMap();
hydrateSyncedContent();

function hydrateSyncedContent(){
  if(page==='home'){
    document.querySelectorAll('.podcast-previews>a').forEach((card,index)=>{
      const feed=podcastFeeds[index];
      if(!feed)return;
      const count=feed[2];
      const badge=card.querySelector('span');
      if(badge)badge.textContent=`${count} ${count===1?'EPISODIO':'EPISODI'}`;
      card.href='podcast.html#programmi';
    });
    const newsList=document.querySelector('.home-news-list');
    if(newsList&&territoryNews.length)newsList.innerHTML=territoryNews.slice(0,3).map(([source,place,date,title,,image,url])=>`<a href="${escapeSyncText(url)}" target="_blank" rel="noreferrer"><span>${escapeSyncText(place)} · ${escapeSyncText(date)}</span><h3>${escapeSyncText(title)}</h3><b aria-label="Leggi su ${escapeSyncText(source)}">↗</b></a>`).join('');
    const eventSlot=document.querySelector('.home-events .event-empty');
    if(eventSlot&&syncedEvents.length)eventSlot.outerHTML=syncedEventsMarkup();
  }
  if(page==='eventi'&&syncedEvents.length){
    const eventSlot=document.querySelector('.page-content .empty-editorial');
    if(eventSlot)eventSlot.outerHTML=syncedEventsMarkup();
  }
}

function renderPage(name){
  const pages={
    progetto:{index:'02',label:'IL PROGETTO',title:'Un hub aperto, radicato, <em>indipendente.</em>',intro:'IMLAND Experience nasce per dare voce alle realtà dei nostri territori. Viviamo in territori ricchi di imprese, persone, competenze ed eccellenze che spesso, proprio perché lontani dai grandi centri, non hanno gli stessi strumenti e le stesse occasioni per raccontarsi, farsi conoscere e creare relazioni. Per questo abbiamo costruito un luogo in cui il territorio possa avere voce: attraverso la radio, i contenuti, gli incontri e una community che mette in relazione aziende, professionisti e persone. Raccontiamo ciò che di valore esiste qui, perché possa essere conosciuto dentro e fuori dal territorio.',image:'',body:`<div class="member-callout"><h2>Dare voce al territorio.</h2><p>Crediamo che musica, informazione ed eventi locali abbiano bisogno di uno spazio comune, aperto e indipendente. Per questo abbiamo costruito un luogo in cui il territorio possa raccontarsi attraverso radio, contenuti, incontri e una community che mette in relazione aziende, professionisti e persone.</p><a class="button primary" href="contatti.html">Proponi una storia →</a></div><div class="story-grid"><article><h2>Radio</h2><p>Diretta 24/7, musica italiana e internazionale, talk e interviste dal territorio.</p><a href="radio.html">Scopri la Radio →</a></article><article><h2>Podcast</h2><p>Serie originali su cibo, cultura, impresa e persone del Piemonte nord-orientale.</p><a href="podcast.html">Esplora i Podcast →</a></article><article><h2>Eventi</h2><p>Radio in tour, dirette live e format su misura, in piazza e nei locali della zona.</p><a href="eventi.html">Scopri gli Eventi →</a></article><article><h2>News del territorio</h2><p>Notizie, persone e iniziative che raccontano ciò che accade nelle nostre province.</p><a href="news.html">Leggi le News →</a></article></div><div class="story-grid"><article><span>01</span><h2>Ascolto del territorio</h2><p>Ogni format nasce da una conversazione reale con chi vive Vercelli, Novara, Biella e Verbania.</p></article><article><span>02</span><h2>Produzione in casa</h2><p>Scriviamo, registriamo e montiamo internamente, con voci e strumenti del territorio.</p></article><article><span>03</span><h2>Collaborazione aperta</h2><p>Aziende, associazioni e persone possono proporre contenuti ed entrare nel palinsesto.</p></article><article><span>04</span><h2>Verifica e cura</h2><p>Ogni episodio e ogni notizia passano da un controllo redazionale prima della pubblicazione.</p></article></div><div class="member-callout"><h2>Il Team IMLAND.</h2><p>Una squadra che vive il territorio e lo trasforma in racconto sonoro: speaker, produzione, Member e organizzazione eventi. Direzione e voci: Davide De Lisa, Massimo Biasini, Matteo Sella, Davide Negro, Alberto Colpo, Alessandra Campaci, Paolo Paracchini, Davide Maiorano, Andrea Libero, Simone Abondio, Sonia Ferraiuolo, Roberto Lisi, Celeste Miolo, Mattia Tassar, Luana Spinella, Luca Golzio, Matteo Pedrina e Alessia Pezzimenti.</p><a class="button primary" href="contatti.html">Conosci il progetto →</a></div>`},
    radio:{index:'03',label:'RADIO',title:'Ascolta le voci del territorio — <em>IMLAND Radio</em>',intro:'La radio che non c\'era.',image:'https://www.imlandradio.it/assets/hero-radio-team-desktop-DPXNvEcc.webp',mobile:'https://www.imlandradio.it/assets/hero-radio-team-mobile-CsjXW9Sa.webp',body:`<div class="signal-card wide"><div class="bars" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i><i></i></div><div><small>IMLAND RADIO · LIVE</small><strong>Ascolta le voci del territorio</strong></div><button type="button" data-play>ASCOLTA ORA</button></div>${radioCatalog(radioPrograms)}<div class="story-grid"><article><h2>Sito e streaming</h2><p>Il player ufficiale è disponibile in ogni pagina, senza registrazione.</p></article><article><h2>Web App IMLAND</h2><p>Diretta, palinsesto e podcast in un’unica esperienza anche in mobilità.</p><a href="download.html">Installa la Web App →</a></article><article><h2>Smart speaker</h2><p>Ascolta IMLAND Radio dal tuo assistente vocale e dai dispositivi connessi.</p></article><article><h2>In auto</h2><p>Collega lo smartphone al Bluetooth dell’auto e porta IMLAND con te.</p></article></div><div class="member-callout"><h2>La radio si fa insieme.</h2><p>Proponi un brano, una rubrica, uno spot, un’ospitata o un nuovo format. Registrazione, montaggio e messa in onda vengono costruiti insieme al team IMLAND.</p><a class="button primary" href="contatti.html">Proponi il tuo progetto radio →</a></div>`},
    podcast:{index:'04',label:'PODCAST',title:'Il territorio ha storie da raccontare — <em>IMLAND Podcast</em>',intro:'Le storie dei protagonisti del territorio.',image:'https://www.imlandradio.it/assets/hero-podcast-team-desktop-CD2lVGzI.webp',mobile:'https://www.imlandradio.it/assets/hero-podcast-team-mobile-BIw807Wn.webp',body:feedCatalog(podcastFeeds)},
    'my-podcast':{index:'05',label:'MY PODCAST',title:'Progetti <em>My Podcast</em>',intro:'I due canali e tutte le relative puntate, aggiornati dai feed ufficiali.',image:'',body:`${feedCatalog(myPodcastFeeds)}<section class="my-podcast"><h2>Hai un progetto da raccontare?</h2><p>Dall’idea alla registrazione, IMLAND costruisce format audio per persone, aziende e realtà del territorio.</p><a class="button primary" href="contatti.html">Proponi il tuo podcast →</a></section>`},
    eventi:{index:'06',label:'EVENTI',title:'Evento Member 2026 <em>segnato sul calendario</em>',intro:'',image:'https://www.imlandradio.it/assets/hero-eventi-member-2026.jpg',body:`<div class="empty-editorial"><span>AGENDA IMLAND</span><h2>Appuntamenti presto in arrivo.</h2><p>Stiamo chiudendo le prossime date con i territori. Qui compariranno esclusivamente eventi confermati.</p><a class="button primary" href="contatti.html">Proponi il tuo evento →</a></div><div class="story-grid"><article><h2>Live e DJ set</h2><p>Musica selezionata, DJ set e momenti di ascolto costruiti sul pubblico dell’evento.</p></article><article><h2>Conduzione e talk</h2><p>Presentazione, interviste e micro-rubriche condotte dalle voci di IMLAND Radio.</p></article><article><h2>Radio in diretta</h2><p>Collegamenti live dal luogo dell’evento, con racconto in onda e sui podcast.</p></article><article><h2>Workshop e laboratori</h2><p>Attività partecipative per scuole, associazioni e community locali.</p></article></div><div class="story-grid"><article><span>01</span><h2>Ci racconti l’evento</h2><p>Data, luogo, pubblico atteso e obiettivo della giornata o della serata.</p></article><article><span>02</span><h2>Costruiamo il format</h2><p>Scegliamo insieme voci, musica e momenti di racconto.</p></article><article><span>03</span><h2>Andiamo in scena</h2><p>Gestiamo animazione, conduzione, contenuti e diretta concordati.</p></article><article><h2>Dove operiamo</h2><p>Vercelli, Novara, Biella, Verbania e tutto il Piemonte nord-orientale.</p></article></div><div class="member-callout"><h2>Portiamo anima al tuo evento.</h2><p>Collaboriamo con aziende, comitati, parrocchie, scuole, associazioni, enti, comuni, commercianti, professionisti e artisti. IMLAND cura la parte umana, culturale e di intrattenimento; catering, palco, permessi e organizzazione generale restano in capo all’organizzatore.</p><a class="button primary" href="contatti.html">Organizza un evento con IMLAND →</a></div>`},
    news:{index:'08',label:'NEWS',title:'Le notizie che raccontano <em>il territorio.</em>',intro:'',image:'',body:`${territoryNewsMarkup()}${memberNewsMarkup()}`},
    member:{index:'07',label:'MEMBER',title:'I membri ufficiali di <em>IMLAND Experience</em>',intro:'La rete che valorizza la conoscenza.',image:'https://www.imlandradio.it/assets/member-network-desktop.png',mobile:'https://www.imlandradio.it/assets/member-network-mobile.png',body:`<div class="member-callout"><h2>Perché diventare Member.</h2><p>Entrare nel cuore di una rete di imprenditori e professionisti del territorio significa creare nuove relazioni, partecipare a eventi esclusivi e accedere a vantaggi dedicati. Una presenza continua nell’ecosistema IMLAND, con più occasioni per raccontare la propria realtà attraverso radio, news e contenuti.</p><a class="button primary" href="https://wa.me/393423535595?text=Salve%2C%20vorrei%20maggiori%20informazioni%20per%20unirmi%20alla%20rete%20IMLAND%20EXPERIENCE." target="_blank" rel="noreferrer">Diventa Member →</a></div>${memberNetworkMarkup()}<div class="territory-strip"><span>VERCELLI</span><span>NOVARA</span><span>BIELLA</span><span>VERBANO CUSIO OSSOLA</span></div>${memberDirectoryMarkup()}${memberNewsMarkup()}`},
    contatti:{index:'09',label:'CONTATTI',title:'Mettiamoci <em>in contatto.</em>',intro:'Scrivici per proporre una storia, un progetto o semplicemente per dirci cosa ne pensi.',image:'',body:`<div class="contact-page"><section class="contact-form-wrap"><div><h2>Scrivici.</h2><p>Raccontaci la tua richiesta. Il modulo aprirà la tua applicazione email con il messaggio già compilato.</p></div><form class="contact-form" data-contact-form><div class="contact-field"><label for="contact-name">Nome</label><input id="contact-name" name="name" type="text" autocomplete="name" required></div><div class="contact-field"><label for="contact-email">Email</label><input id="contact-email" name="email" type="email" autocomplete="email" required></div><div class="contact-field full"><label for="contact-topic">Argomento</label><select id="contact-topic" name="topic" required><option value="">Scegli un argomento</option><option>Storia / segnalazione</option><option>Radio / podcast</option><option>Evento / partnership</option><option>Member</option><option>Altro</option></select></div><div class="contact-field full"><label for="contact-message">Messaggio</label><textarea id="contact-message" name="message" rows="7" required></textarea></div><label class="contact-privacy full"><input type="checkbox" required><span>Dichiaro di aver letto la Privacy Policy.</span></label><button class="contact-submit full" type="submit">Invia messaggio →</button><p class="contact-status full" role="status" aria-live="polite"></p></form></section><section class="contact-details"><div class="contact-direct"><h2>Contatti diretti.</h2><a href="mailto:info@imlandradio.com"><span>Email</span><strong>info@imlandradio.com</strong><small>Redazione, radio, eventi e community.</small></a><a href="tel:+393514323003"><span>Telefono</span><strong>+39 351 432 3003</strong><small>Chiamaci in orario studio.</small></a><div class="studio-hours"><span>Orari studio</span><strong>Lun–ven, 9:00–19:00</strong><small>Vercelli e provincia · Piemonte nord-orientale</small></div></div><div class="company-data"><h2>Dati societari &amp; licenze.</h2><dl><div><dt>Ragione sociale</dt><dd>IMLAND EXPERIENCE SRL</dd></div><div><dt>Partita IVA</dt><dd>02802650024</dd></div><div><dt>Licenza SIAE</dt><dd>202500000226</dd></div><div><dt>Licenza SCF</dt><dd>116/5/24</dd></div></dl></div><div class="contact-social"><h2>Seguici.</h2><div><a href="https://www.instagram.com/imland_radio/" target="_blank" rel="noreferrer">Instagram ↗</a><a href="https://www.facebook.com/imlandradio" target="_blank" rel="noreferrer">Facebook ↗</a><a href="https://www.linkedin.com/company/imland-experience/" target="_blank" rel="noreferrer">LinkedIn ↗</a><a href="https://open.spotify.com/search/imland%20radio" target="_blank" rel="noreferrer">Spotify ↗</a><a href="https://www.youtube.com/results?search_query=imland+radio" target="_blank" rel="noreferrer">YouTube ↗</a><a href="https://t.me/imlandradio" target="_blank" rel="noreferrer">Telegram ↗</a></div></div></section></div>`},
    privacy:{index:'',label:'PRIVACY',title:'Privacy <em>Policy.</em>',intro:'Informazioni sul trattamento dei dati personali ai sensi del Regolamento UE 2016/679.',image:'https://www.imlandradio.it/assets/hero-carousel/novara-desktop-1.webp',body:`<div class="legal-copy"><h2>Titolare del trattamento</h2><p><strong>IMLAND EXPERIENCE SRL</strong>, C.F. e P.IVA 02802650024, REA VC-316051, sede legale in Via Costantino Durio 16, 13019 Varallo (VC). Per richieste privacy: <a href="mailto:imlandexperience@gmail.com">imlandexperience@gmail.com</a>.</p><h2>Dati e finalità</h2><p>Possiamo trattare dati identificativi e di contatto, dati di account e profilo, messaggi, proposte, candidature, dati tecnici e preferenze cookie per fornire i servizi richiesti, rispondere ai contatti, garantire sicurezza, adempiere agli obblighi di legge e, solo con consenso, inviare newsletter o attivare analisi e marketing.</p><h2>Conservazione e destinatari</h2><p>I dati sono conservati per il tempo necessario alle finalità dichiarate e possono essere trattati da personale autorizzato e fornitori necessari a hosting, database, email, assistenza e sicurezza. Eventuali trasferimenti fuori dallo SEE avvengono con le garanzie previste dal GDPR.</p><h2>I tuoi diritti</h2><p>Puoi chiedere accesso, rettifica, cancellazione, limitazione, portabilità e opposizione, revocare il consenso e proporre reclamo al Garante per la protezione dei dati personali.</p><a class="button primary" href="contatti.html">Contatta IMLAND →</a></div>`},
    cookie:{index:'',label:'COOKIE',title:'Cookie <em>Policy.</em>',intro:'Come utilizziamo cookie e tecnologie simili sul sito IMLAND.',image:'https://www.imlandradio.it/assets/hero-carousel/biella-desktop-1.webp',body:`<div class="legal-copy"><h2>Cookie tecnici</h2><p>Sono necessari al funzionamento del sito e alla memorizzazione delle preferenze. Non richiedono consenso.</p><h2>Analisi e marketing</h2><p>Gli strumenti facoltativi di analisi o marketing vengono attivati solo dopo una scelta positiva. Il rifiuto non limita i servizi essenziali.</p><h2>Gestione delle preferenze</h2><p>Puoi modificare o revocare la scelta in qualsiasi momento. Il browser permette inoltre di cancellare cookie e memorie locali; il blocco degli strumenti tecnici può compromettere accesso e preferenze.</p><p>Titolare: IMLAND EXPERIENCE SRL · P.IVA 02802650024 · <a href="mailto:imlandexperience@gmail.com">imlandexperience@gmail.com</a></p></div>`},
    termini:{index:'',label:'TERMINI',title:'Termini e <em>Condizioni.</em>',intro:'Condizioni di utilizzo del sito e dei servizi IMLAND.',image:'https://www.imlandradio.it/assets/hero-carousel/vercelli-desktop-1.webp',body:`<div class="legal-copy"><h2>Gestore e servizi</h2><p>Il sito è gestito da IMLAND EXPERIENCE SRL, C.F. e P.IVA 02802650024, REA VC-316051, sede legale in Via Costantino Durio 16, 13019 Varallo (VC). Le condizioni regolano sito, radio, podcast, eventi, aree riservate, servizi Member e contenuti editoriali.</p><h2>Regole di utilizzo</h2><p>È vietato pubblicare contenuti illeciti, falsi, discriminatori, diffamatori o lesivi, inviare malware o spam, tentare accessi non autorizzati o interferire con sicurezza e funzionamento.</p><h2>Contenuti e proprietà intellettuale</h2><p>Marchi, loghi, grafica, software, testi, immagini, audio e format appartengono a IMLAND o ai rispettivi titolari. Le notizie di terzi restano attribuite alle fonti indicate. Diffusione musicale: licenza SIAE 202500000226 e SCF 116/5/24.</p><h2>Legge applicabile</h2><p>Si applica la legge italiana, fatti salvi i diritti inderogabili del consumatore. Per assistenza e contestazioni scrivi a <a href="mailto:imlandexperience@gmail.com">imlandexperience@gmail.com</a>.</p></div>`},
    faq:{index:'10',label:'FAQ',title:'Tutto quello che vuoi <em>sapere.</em>',intro:'Risposte chiare su radio, podcast, eventi, Member, supporto e news.',image:'',body:`<div class="faq-list">
      <section class="faq-category faq-radio"><header><h2><svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="14.5" cy="13.5" r="3.5"/><path d="M2 13.5C2 9.74 2 7.86 3.05 6.61C4.31 5 6.3 5 10.5 5h3c4.2 0 6.19 0 7.45 1.61C22 7.86 22 9.74 22 13.5s0 5.64-1.05 6.89C19.69 22 17.7 22 13.5 22h-3c-4.2 0-6.19 0-7.45-1.61C2 19.14 2 17.26 2 13.5Z"/><path d="m10 5 4-3M6 12h1m-1 3h1"/></svg><span>Radio</span></h2><p>Diretta, palinsesto e canali di ascolto.</p></header><details><summary>Come si ascolta la radio di IMLAND?</summary><p>Puoi ascoltare gratuitamente IMLAND Radio dalla pagina Radio e dal player presente sul sito, dall’app IMLAND, su TuneIn, su myTuner Radio e tramite smart speaker. La diretta è disponibile 24 ore su 24.</p></details><details><summary>Dove trovo il palinsesto?</summary><p>Il palinsesto aggiornato è disponibile nella pagina Radio, con giorni, orari e programmi in onda.</p></details></section>
      <section class="faq-category faq-podcast"><header><h2><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M4.5 21.5 8.5 17.5m2 0 4 4m-5-4v5M2 11.88c0-2.07 0-3.1 1.03-3.74C4.05 7.5 5.7 7.5 9 7.5h1c3.3 0 4.95 0 5.97.64C17 8.78 17 9.81 17 11.88v1.24c0 2.07 0 3.1-1.03 3.74-1.02.64-2.67.64-5.97.64H9c-3.3 0-4.95 0-5.97-.64C2 16.22 2 15.19 2 13.12v-1.24Z"/><path d="M17 10.25c2.24-1.34 3.36-2 4.15-1.67.85.3.85 1.32.85 3.35v1.14c0 2.03 0 3.05-.85 3.35-.79.33-1.91-.33-4.15-1.67"/><circle cx="12.5" cy="5" r="2.5"/><circle cx="7" cy="4.5" r="3"/></svg><span>Podcast</span></h2><p>Format editoriali e produzioni audio.</p></header><details><summary>Dove trovo i podcast IMLAND?</summary><p>Nella sezione Podcast trovi i format editoriali e tutte le puntate disponibili. My Podcast è lo spazio dedicato ai progetti audio realizzati su misura per aziende e organizzazioni.</p></details><details><summary>Posso proporre un podcast?</summary><p>Sì. Dalla pagina Contatti puoi presentare l’idea, il tema e gli obiettivi del progetto: il team valuterà insieme a te il percorso più adatto.</p></details></section>
      <section class="faq-category faq-eventi"><header><h2><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M16 2v4M8 2v4m5-2h-2C7.23 4 5.34 4 4.17 5.17 3 6.34 3 8.23 3 12v2c0 3.77 0 5.66 1.17 6.83C5.34 22 7.23 22 11 22h2c3.77 0 5.66 0 6.83-1.17C21 19.66 21 17.77 21 14v-2c0-3.77 0-5.66-1.17-6.83C18.66 4 16.77 4 13 4ZM3 10h18"/><path d="M7.5 14h.12m4.38 0h.12m4.38 0h.12M7.5 18h.12m4.38 0h.12"/></svg><span>Eventi</span></h2><p>Il contributo di IMLAND all’interno degli eventi.</p></header><details><summary>Che ruolo può avere IMLAND in un evento?</summary><p>A seconda del progetto, IMLAND può entrare all’interno di un evento occupandosi di animazione, conduzione, radio, produzione di contenuti e service tecnico audio, quando previsto. L’organizzazione complessiva dell’evento rimane in capo all’organizzatore.</p></details><details><summary>IMLAND dispone di un impianto audio?</summary><p>IMLAND dispone del service tecnico necessario alla produzione e diffusione del suono, quando previsto dal progetto. IMLAND non fornisce il palco e non fornisce il catering; questi aspetti restano in capo all’organizzatore.</p></details><details><summary>IMLAND organizza l’intero evento?</summary><p>No. IMLAND interviene con i servizi concordati per il singolo progetto, mentre la responsabilità dell’organizzazione complessiva rimane in capo all’organizzatore.</p></details></section>
      <section class="faq-category faq-member"><header><h2><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18.5 20.5c-.23-2.93-2.66-5.25-5.69-5.45L12 15c-.29.01-.56.02-.81.03-3.01.14-5.46 2.57-5.69 5.47"/><circle cx="12" cy="9.25" r="3.25"/><path d="M5.5 8.5a3.25 3.25 0 0 1 4-4.75m9 4.75a3.25 3.25 0 0 0-4-4.75M22 18c-.18-2.26-2-4.5-4-5M2 18c.18-2.26 2-4.5 4-5"/></svg><span>Member</span></h2><p>Vantaggi, rete e visibilità.</p></header><details><summary>Come si diventa Member di IMLAND?</summary><p>Chi desidera diventare Member deve entrare in contatto direttamente con IMLAND. Il team illustrerà funzionamento, vantaggi e modalità di adesione.</p></details><details><summary>A chi è rivolta la rete Member?</summary><p>La rete è rivolta ad aziende, professionisti e realtà del territorio interessati a conoscere IMLAND e a valutare un percorso di adesione direttamente con il team.</p></details></section>
      <section class="faq-category faq-supporto"><header><h2><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M17 10.8c0-.8.2-1.1 1-1.47.45-.2.67-.31.9-.33.25-.02.5.04.72.16.28.16.48.46.69.71.94 1.15 1.41 1.72 1.59 2.35.14.51.14 1.04 0 1.55-.25.92-1.05 1.69-1.64 2.4-.3.37-.45.55-.64.66-.22.12-.47.18-.72.16-.22-.02-.45-.12-.9-.33-.8-.36-1-.67-1-1.47V10.8ZM7 10.8c0-.8-.2-1.1-1-1.47-.45-.2-.67-.31-.9-.33-.67-.05-1.03.4-1.41.87-.94 1.15-1.41 1.72-1.59 2.35-.14.51-.14 1.04 0 1.55.25.92 1.05 1.69 1.64 2.4.37.45.73.86 1.36.81.23-.02.45-.12.9-.33.8-.36 1-.67 1-1.47V10.8Z"/><path d="M5 9c0-3.31 3.13-6 7-6s7 2.69 7 6m0 8v.8c0 1.77-1.79 3.2-4 3.2h-2"/></svg><span>Community e supporto tecnico</span></h2><p>Partecipazione, sito, app e player.</p></header><details><summary>Come posso partecipare alla community IMLAND?</summary><p>Puoi ascoltare i contenuti, partecipare agli appuntamenti, proporre storie e iniziative oppure entrare in contatto con la rete Member. La pagina Contatti raccoglie tutti i riferimenti utili.</p></details><details><summary>Cosa faccio se il sito, l’app o il player non funzionano?</summary><p>Verifica la connessione, aggiorna la pagina e prova con un browser aggiornato. Se il problema continua, scrivici dalla pagina Contatti indicando dispositivo, browser e una breve descrizione dell’errore.</p></details></section>
      <section class="faq-category faq-news"><header><h2><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M18 15V9c0-2.83 0-4.24-.88-5.12C16.24 3 14.83 3 12 3H8c-2.83 0-4.24 0-5.12.88C2 4.76 2 6.17 2 9v6c0 2.83 0 4.24.88 5.12C3.76 21 5.17 21 8 21h12M6 8h8m-8 4h8m-8 4h4"/><path d="M18 8h1c1.41 0 2.12 0 2.56.44.44.44.44 1.15.44 2.56v8a2 2 0 0 1-4 0V8Z"/></svg><span>News</span></h2><p>Notizie del territorio e notizie dei Member.</p></header><details><summary>Qual è la differenza tra News del territorio e News dei Member?</summary><p>Le News del territorio raccontano fatti, persone e iniziative delle province in cui opera IMLAND. Le News dei Member sono uno spazio dedicato alle novità delle realtà che fanno parte della rete Member.</p></details><details><summary>Come posso segnalare una notizia?</summary><p>Puoi inviare la segnalazione dalla pagina Contatti, indicando le informazioni essenziali e le fonti disponibili. La redazione valuta i contenuti prima della pubblicazione.</p></details><details><summary>Essere Member garantisce la pubblicazione di una notizia?</summary><p>Le News dei Member sono uno spazio dedicato alla rete, ma ogni contenuto viene comunque valutato e organizzato dalla redazione in coerenza con il progetto editoriale.</p></details></section>
    </div>`}
  };
  const p=pages[name];
  const heroActions={
    progetto:`<a class="button primary" href="#contenuti">Scopri il progetto</a><a class="button ghost" href="contatti.html">Porta la tua voce</a>`,
    radio:`<button class="button primary" type="button" data-play>Ascolta ora</button><a class="button ghost" href="#palinsesto">Vedi il palinsesto</a>`,
    podcast:`<a class="button primary" href="#programmi">Esplora i programmi</a>`,
    'my-podcast':`<a class="button primary" href="#programmi">Scopri i progetti</a><a class="button ghost" href="contatti.html">Proponi il tuo podcast</a>`,
    eventi:`<a class="button primary" href="#calendario">Scopri gli eventi</a><a class="button ghost" href="#porta-evento">Proponi il tuo evento</a>`,
    member:`<a class="button primary" href="https://wa.me/393423535595?text=Salve%2C%20vorrei%20maggiori%20informazioni%20per%20unirmi%20alla%20rete%20IMLAND%20EXPERIENCE." target="_blank" rel="noreferrer">Diventa Member</a>`,
    news:`<a class="button primary" href="#notizie">Leggi le News</a><a class="button ghost" href="contatti.html">Segnala una notizia</a>`,
    contatti:`<a class="button primary" href="#scrivici">Compila il form</a><a class="button ghost" href="mailto:info@imlandradio.com">Scrivi una email</a>`,
  };
  const extras={
    podcast:`<section class="content-extension"><div class="story-grid"><article><h2>Business</h2><p>Imprese, professionisti, filiere e strumenti raccontati dalle voci del territorio.</p></article><article><h2>Cultura</h2><p>Libri, persone, luoghi e identità del Piemonte nord-orientale.</p></article><article><h2>Cibo</h2><p>Produttori, vino, agricoltura e percorsi del gusto.</p></article><article><h2>Tecnologia e lifestyle</h2><p>Cultura pop, attualità e storie contemporanee da ascoltare quando vuoi.</p></article></div><div class="member-callout"><h2>Ascolta dove preferisci.</h2><p>Tutte le puntate sono disponibili direttamente nel player IMLAND. Puoi inoltre cercare IMLAND sulle principali piattaforme podcast.</p><a class="button primary" href="my-podcast.html">Scopri My Podcast →</a></div><div class="faq-list compact-faq"><details><summary>Dove posso ascoltare i podcast IMLAND?</summary><p>Direttamente sul sito, aprendo il canale e scegliendo la puntata desiderata.</p></details><details><summary>Ogni quanto escono nuovi episodi?</summary><p>Ogni programma segue il proprio calendario editoriale. I feed ufficiali mostrano sempre le ultime pubblicazioni.</p></details><details><summary>Come propongo un ospite o una storia?</summary><p>Usa la pagina Contatti e seleziona Radio / podcast come argomento.</p></details></div></section>`,
    'my-podcast':`<section class="content-extension"><div class="story-grid"><article><span>01</span><h2>Idea e registrazione</h2><p>Costruiamo il format e registriamo il progetto con il supporto dello studio.</p></article><article><span>02</span><h2>Produzione</h2><p>Seguiamo il podcast dall’idea alla lavorazione, con un percorso su misura.</p></article><article><span>03</span><h2>Pubblicazione</h2><p>Prepariamo il progetto per la pubblicazione e la distribuzione concordata.</p></article><article><h2>Un progetto tuo</h2><p>Microfoni, studio, competenze e produzione per aziende e organizzazioni.</p><a href="contatti.html">Proponi il tuo podcast →</a></article></div></section>`,
    eventi:`<section class="content-extension"><div class="story-grid"><article><h2>Aziende</h2><p>Team building, inaugurazioni, feste e convention con animazione su misura.</p></article><article><h2>Comitati ed enti</h2><p>Feste patronali, sagre, rassegne culturali e appuntamenti in piazza.</p></article><article><h2>Scuole e associazioni</h2><p>Laboratori, open day e format partecipativi per studenti e community.</p></article><article><h2>Commercianti e artisti</h2><p>Shopping night, showcase, presentazioni e momenti creativi dal vivo.</p></article></div><div class="member-callout"><h2>Cosa serve da chi organizza.</h2><p>Uno spazio per voce e regia, corrente elettrica, un referente, il programma indicativo e le autorizzazioni necessarie. Impianto audio e service vengono definiti in base al progetto.</p><a class="button primary" href="contatti.html">Parliamo del tuo evento →</a></div><div class="faq-list compact-faq"><details><summary>IMLAND organizza l’intero evento?</summary><p>No. IMLAND cura i servizi concordati; l’organizzazione generale resta in capo all’organizzatore.</p></details><details><summary>Potete trasmettere in diretta?</summary><p>Sì, quando il luogo e il progetto consentono il collegamento radio.</p></details><details><summary>Chi gestisce permessi e SIAE?</summary><p>Le autorizzazioni dell’evento restano in capo all’organizzatore.</p></details></div></section>`,
    news:`<section class="content-extension"><div class="member-callout"><h2>Una rassegna, fonti sempre visibili.</h2><p>IMLAND seleziona notizie pubblicate da testate del territorio. Titoli, immagini e informazioni restano attribuiti alla fonte indicata e ogni card apre l’articolo originale. IMLAND non è una testata giornalistica.</p><a class="button primary" href="contatti.html">Segnala una notizia →</a></div></section>`,
    contatti:`<section class="content-extension"><div class="story-grid"><article><h2>Proponi una storia</h2><p>Conosci un progetto o una persona del territorio che merita spazio in radio o podcast? Seleziona “Storia / segnalazione” nel form e raccontacela.</p></article><article><h2>Link utili</h2><p><a href="eventi.html">Scopri gli Eventi →</a><br><a href="radio.html">Ascolta IMLAND Radio →</a><br><a href="podcast.html">Esplora i Podcast →</a><br><a href="member.html">Diventa Member →</a></p></article></div><div class="faq-list compact-faq"><details><summary>In quanto tempo ricevo una risposta?</summary><p>Il team risponde appena possibile durante gli orari di studio.</p></details><details><summary>Posso proporre una storia?</summary><p>Sì. Invia informazioni essenziali e fonti disponibili dal modulo qui sopra.</p></details><details><summary>Avete una sede fisica?</summary><p>IMLAND opera nel Piemonte nord-orientale. Contatta il team prima di organizzare una visita.</p></details></div></section>`,
    faq:`<section class="content-extension"><div class="member-callout"><h2>Hai ancora una domanda?</h2><p>Scrivi direttamente al team IMLAND e raccontaci di cosa hai bisogno.</p><a class="button primary" href="contatti.html">Contattaci →</a></div></section>`
  };
  const actionMarkup=heroActions[name]?`<div class="page-hero-actions">${heroActions[name]}</div>`:'';
  const imageMarkup=p.image?`<picture><source media="(max-width: 800px)" srcset="${p.mobile||p.image}"><img src="${p.image}" alt=""></picture>`:'';
  const introMarkup=p.intro?`<p>${p.intro}</p>`:'';
  return `<section class="page-hero${p.image?'':' page-hero-editorial'}">${imageMarkup}<div class="page-hero-wash"></div><div class="page-hero-copy"><p class="eyebrow">${p.index} / ${p.label}</p><h1>${p.title}</h1>${introMarkup}${actionMarkup}</div></section><section id="contenuti" class="page-content section-paper"><div id="${name==='radio'?'palinsesto':name==='podcast'||name==='my-podcast'?'programmi':name==='eventi'?'calendario':name==='member'?'rete-member':name==='news'?'notizie':name==='contatti'?'scrivici':name==='faq'?'domande':'pagina'}"></div>${p.body}${extras[name]||''}</section>`;
}

function renderFooter(){return `<footer><div class="footer-brand"><span>IMLAND</span><b>EXPERIENCE</b><p>Dai voce al tuo territorio.</p></div><div><h3>Esplora</h3>${nav.map(([href,label])=>`<a href="${href}">${label}</a>${href==='podcast.html'?'<a href="my-podcast.html">My Podcast</a>':''}`).join('')}<a href="download.html">Scarica l’App</a></div><div><h3>Contatti</h3><a href="mailto:info@imlandradio.com">info@imlandradio.com</a><a href="tel:+393514323003">+39 351 432 3003</a><a href="https://www.instagram.com/imland_radio/">Instagram</a><a href="https://www.facebook.com/imlandradio">Facebook</a></div><div class="legal"><p>IMLAND EXPERIENCE SRL<br>P.IVA 02802650024</p><p>Licenza SIAE 202500000226<br>Licenza SCF 116/5/24</p><p><a href="privacy.html">Privacy</a><br><a href="cookie.html">Cookie</a><br><a href="termini.html">Termini e condizioni</a></p></div><div class="footer-bottom"><span>© 2026 IMLAND EXPERIENCE</span><span>Progetto web BIXONT.IT</span></div></footer>`}
function enhanceContactIcons(){const icons={mail:'<svg viewBox="0 0 24 24" aria-hidden="true"><rect x="3" y="5" width="18" height="14" rx="3"/><path d="m4 7 8 6 8-6"/></svg>',phone:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M8 3.5 5.4 4.8c-.7.35-1.05 1.13-.85 1.88 1.5 5.6 7.38 11.48 12.98 12.98.75.2 1.53-.15 1.88-.85L20.5 16l-4.1-2.15-1.72 2.02a14.2 14.2 0 0 1-6.55-6.55l2.02-1.72L8 3.5Z"/></svg>',hours:'<svg viewBox="0 0 24 24" aria-hidden="true"><circle cx="12" cy="12" r="8.5"/><path d="M12 7v5l3.5 2"/></svg>',social:'<svg viewBox="0 0 24 24" aria-hidden="true"><path d="M5 19 19 5M8 5h11v11"/></svg>'};document.querySelectorAll('.contact-direct>a,.studio-hours').forEach((item,index)=>item.insertAdjacentHTML('afterbegin',`<span class="contact-icon" aria-hidden="true">${index===0?icons.mail:index===1?icons.phone:icons.hours}</span>`));document.querySelectorAll('.contact-social a').forEach(item=>item.insertAdjacentHTML('afterbegin',`<span class="contact-social-icon" aria-hidden="true">${icons.social}</span>`));}
function initMemberDome(){const root=document.querySelector('[data-member-dome]');const sphere=root?.querySelector('[data-dome-sphere]');const viewer=root?.querySelector('[data-dome-viewer]');if(!root||!sphere||!viewer)return;let rotation={x:-2,y:0},start={x:0,y:0,rx:0,ry:0},dragging=false,moved=false,ignoreClick=false;const apply=()=>{sphere.style.transform=`translateZ(calc(var(--dome-radius) * -1)) rotateX(${rotation.x}deg) rotateY(${rotation.y}deg)`};apply();root.addEventListener('pointerdown',event=>{if(event.target.closest('[data-member-logo],.dome-viewer'))return;dragging=true;moved=false;start={x:event.clientX,y:event.clientY,rx:rotation.x,ry:rotation.y};root.setPointerCapture?.(event.pointerId);root.classList.add('is-dragging')});root.addEventListener('pointermove',event=>{if(!dragging)return;const dx=event.clientX-start.x,dy=event.clientY-start.y;if(Math.hypot(dx,dy)>4)moved=true;rotation.y=start.ry+dx/12;rotation.x=Math.max(-9,Math.min(9,start.rx-dy/18));apply()});const finish=()=>{if(!dragging)return;dragging=false;root.classList.remove('is-dragging');if(moved){ignoreClick=true;setTimeout(()=>{ignoreClick=false},90)}};root.addEventListener('pointerup',finish);root.addEventListener('pointercancel',finish);root.querySelectorAll('[data-member-logo]').forEach(button=>button.addEventListener('click',()=>{if(ignoreClick)return;const image=viewer.querySelector('img');image.src=button.dataset.image;image.alt=button.dataset.name;viewer.querySelector('[data-dome-name]').textContent=button.dataset.name;viewer.hidden=false;viewer.querySelector('[data-dome-close]').focus()}));const close=()=>{viewer.hidden=true;root.querySelector('[data-member-logo]')?.focus()};viewer.querySelector('[data-dome-close]').addEventListener('click',close);document.addEventListener('keydown',event=>{if(event.key==='Escape'&&!viewer.hidden)close()})}
